style.css:
@-moz-document domain("pinterest.com") {
/* 1. FONDO DE LA PÁGINA: Rosa Pastel con Círculos Blancos */
    body, html, #initial-focus-container, [data-test-id="grid"], .App, main, [style*="background-color"] {
        background-color: #FFDEE9 !important;
        background-image: radial-gradient(#FFFFFF 20%, transparent 20%),
                          radial-gradient(#FFFFFF 20%, transparent 20%) !important;
        background-size: 30px 30px !important;
        background-position: 0 0, 15px 15px !important;
    }

    /* 2. ICONOS (Casita, Mensajes, Notificaciones): Todo en un hermoso Rosa */
    svg, 
    path, 
    circle,
    [role="img"],
    [data-test-id="navigation-bar"] svg,
    .gUZ,
    .U90 {
        fill: #FF8AAB !important; /* Rosa más vivo para que resalte sobre los círculos */
        color: #FF8AAB !important;
    }

    /* 3. TEXTOS E INFORMACIÓN DE LAS PUBLICACIONES: Rosa */
    h1, h2, h3, div, span, p, [data-test-id="pin-title"], [data-test-id="official-user-name"] {
        color: #FF8AAB !important;
    }

    /* 4. ZONA DE BÚSQUEDA: Se queda en Blanco puro */
    /* Forzamos a que la barra de arriba sea blanca */
    [data-test-id="search-box-container"],
    form[role="search"],
    .RNNXgb,
    input[type="text"] {
        background-color: #FFFFFF !important;
        border-radius: 24px !important; /* Mantiene la forma redondeada estética */
    }

    /* El texto que tú escribes dentro de la barra de búsqueda se verá gris oscuro */
    input[type="text"], .gLFyf, [data-test-id="search-box-input"] {
        color: #4A4A4A !important;
    }

    /* La lupita que está dentro de la barra de búsqueda se queda en gris/rosa suave */
    [data-test-id="search-box-search-icon"] svg,
    [data-test-id="search-box-search-icon"] path {
        fill: #767676 !important;
        color: #767676 !important;
    }
}
